    complex<double>step=polar(1.0,-2*pi/length);
    for(int i=0;i<n;i+=length){
        complex<double>factor=1;
        for(int j=0;j<length/2;j++){
            complex<double>u=a[i+j],v=a[i+j+length/2]*factor;
            a[i+j]=u+v;a[i+j+length/2]=u-v;factor*=step;
        }
    }
}
for(auto value:a)cout<<value.real()<<" "<<value.imag()<<"\n";
return 0;
}

